import{_ as e}from"./chunks/exchange.WBTyBzew.js";import{_ as r,o as t,c as i,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Кошелёк, почта и рынок","description":"","frontmatter":{"pageId":"players/economy","contentRevision":1},"headers":[],"relativePath":"ru/players/economy.md","filePath":"ru/players/economy.md"}'),l={name:"ru/players/economy.md"};function s(n,a,c,p,d,m){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="кошелек-почта-и-рынок" tabindex="-1">Кошелёк, почта и рынок <a class="header-anchor" href="#кошелек-почта-и-рынок" aria-label="Permalink to &quot;Кошелёк, почта и рынок&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><img class="wiki-art" src="'+e+'" alt="Обмен проходит через серверный escrow; доставка — через почту." width="960" height="440"><p class="wiki-caption">Обмен проходит через серверный escrow; доставка — через почту.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Для штатных операций нужны консоль связи и запитанные торговые маяки; предметы выбираются из обслуживаемой зоны. Кошелёк — серверный баланс серебра, а не стопка на карте. Внесение серебра переносит его в баланс; вывод доставляется через серверную посылку.</p><p>Выставь предметы или пешку обычным лотом, задай цену и проверь состав. Покупатель платит кошельком, товар уходит в доставку, продавец получает выручку с учётом комиссии. Непроданные лоты по умолчанию истекают через 30 дней.</p><p>Проверяй почту после сделки и обрыва соединения. Сервер удерживает отправленное в эскроу до завершения, а возвраты оформляет посылками.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>По умолчанию хранение после 3 бесплатных дней стоит 0,5% в сутки. Долг, угроза на карте, заморозка или запрещённые defName ограничивают операции. Комиссии и лимиты задаёт сервер.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./gifts-trades">Подарки и двусторонние сделки</a></li><li><a href="./auctions">Аукционы</a></li><li><a href="./procurement">Заказы, контракты и общие цели</a></li></ul>',12)])])}const f=r(l,[["render",s]]);export{u as __pageData,f as default};
